select p.id, v.slug, v.theme, v.text, v.difficulty, 30 from packs p, (values
  ('landlocked', 'physical', 'Name a landlocked country', 1),
  ('no-land-borders', 'physical', 'Name a country with no land borders', 2),
  ('area-over-1m', 'physical', 'Name a country larger than 1,000,000 km²', 2),
  ('area-under-1k', 'physical', 'Name a country smaller than 1,000 km²', 2),
  ('region-africa', 'region', 'Name a country in Africa', 1),
  ('region-asia', 'region', 'Name a country in Asia', 1),
  ('region-europe', 'region', 'Name a country in Europe', 1),
  ('region-oceania', 'region', 'Name a country in Oceania', 4),
  ('region-south-america', 'region', 'Name a country in South America', 4),
  ('region-north-central-america', 'region', 'Name a country in North or Central America, or the Caribbean', 3),
  ('region-caribbean', 'region', 'Name a country in the Caribbean', 4),
  ('region-west-africa', 'region', 'Name a country in West Africa', 3),
  ('region-east-africa', 'region', 'Name a country in East Africa', 3),
  ('region-central-africa', 'region', 'Name a country in Central Africa', 4),
  ('region-western-asia', 'region', 'Name a country in Western Asia (Middle East and Caucasus)', 3),
  ('region-southeast-asia', 'region', 'Name a country in Southeast Asia', 4),
  ('region-northern-europe', 'region', 'Name a country in Northern Europe', 4),
  ('borders-china', 'borders', 'Name a country that borders China', 4),
  ('borders-russia', 'borders', 'Name a country that borders Russia', 4),
  ('borders-germany-france', 'borders', 'Name a country that borders Germany or France', 4),
  ('borders-6-plus', 'borders', 'Name a country that borders at least 6 other countries', 2),
  ('borders-exactly-1', 'borders', 'Name a country that borders exactly one other country', 3),
  ('language-english', 'language', 'Name a country where English is an official language', 1),
  ('language-french', 'language', 'Name a country where French is an official language', 2),
  ('language-arabic', 'language', 'Name a country where Arabic is an official language', 2),
  ('language-spanish', 'language', 'Name a country where Spanish is an official language', 3),
  ('currency-euro', 'currency', 'Name a country that uses the euro', 2),
  ('currency-dollar', 'currency', 'Name a country whose currency is called a dollar', 2),
  ('currency-franc', 'currency', 'Name a country whose currency is called a franc', 3),
  ('starts-s', 'letters', 'Name a country that starts with S', 2),
  ('starts-m', 'letters', 'Name a country that starts with M', 3),
  ('starts-b', 'letters', 'Name a country that starts with B', 3),
  ('starts-c', 'letters', 'Name a country that starts with C', 3),
  ('starts-a', 'letters', 'Name a country that starts with A', 4),
  ('starts-g', 'letters', 'Name a country that starts with G', 4),
  ('starts-n', 'letters', 'Name a country that starts with N', 4),
  ('starts-t', 'letters', 'Name a country that starts with T', 4),
  ('starts-p', 'letters', 'Name a country that starts with P', 4),
  ('ends-ia', 'letters', 'Name a country whose name ends in -ia', 1),
  ('two-words', 'letters', 'Name a country with two or more words in its name', 2),
  ('contains-z', 'letters', 'Name a country with a Z in its name', 3),
  ('contains-k', 'letters', 'Name a country with a K in its name', 3),
  ('same-first-last', 'letters', 'Name a country whose name starts and ends with the same letter', 3),
  ('five-letters-or-fewer', 'letters', 'Name a country with 5 letters or fewer in its name', 1),
  ('capital-starts-b', 'capital', 'Name a country whose capital starts with B', 2),
  ('capital-starts-m', 'capital', 'Name a country whose capital starts with M', 3),
  ('capital-starts-s', 'capital', 'Name a country whose capital starts with S', 3),
  ('capital-starts-a', 'capital', 'Name a country whose capital starts with A', 3),
  ('capital-starts-p', 'capital', 'Name a country whose capital starts with P', 3),
  ('capital-starts-k', 'capital', 'Name a country whose capital starts with K', 4),
  ('capital-starts-l', 'capital', 'Name a country whose capital starts with L', 4),
